  const kids = [[]], depth = [0], vals = [r.int(0, maxV)];
  const deepFirst = big && r.bool() ? r.int(100, 299) : 0;
  for (let i = 1; i < n; i++) {
    let p = i <= deepFirst ? i - 1 : r.int(0, i - 1);
    while (depth[p] >= 299) p = r.int(0, i - 1);
    kids.push([]); depth.push(depth[p] + 1); vals.push(r.int(0, maxV));
    kids[p].push(i);
  }
  const nest = i => [vals[i], kids[i].map(nest)];
  return [nest(0)];
