class Node:
    def __init__(self, val, children=None):
        self.val = val
        self.children = children or []


def serialize(root):
    if not root:
        return ""
    out = []

    def walk(n):
        out.append(str(n.val))
        out.append(str(len(n.children)))
        for c in n.children:
            walk(c)

    walk(root)
    return ",".join(out)


def deserialize(data):
    if data == "":
        return None
    tok = data.split(",")
    pos = 0

    def read():
        nonlocal pos
        node = Node(int(tok[pos]))
        count = int(tok[pos + 1])
        pos += 2
        for _ in range(count):
            node.children.append(read())
        return node

    return read()


class Solution:
    def roundTrip(self, root):
        def to_node(t):
            return Node(t[0], [to_node(c) for c in t[1]])

        def to_nested(n):
            return [n.val, [to_nested(c) for c in n.children]]

        rebuilt = deserialize(serialize(to_node(root) if root is not None else None))
        return to_nested(rebuilt) if rebuilt else None

