type Nested = [number, Nested[]];

class Node {
  children: Node[] = [];
  constructor(public val: number) {}
}

function serialize(root: Node | null): string {
  if (!root) return "";
  const out: string[] = [String(root.val)];
  const queue = [root];
  for (let h = 0; h < queue.length; h++) {
    for (const c of queue[h].children) { out.push(String(c.val)); queue.push(c); }
    out.push("#"); // end of this node's children
  }
  return out.join(",");
}

function deserialize(data: string): Node | null {
  if (data === "") return null;
  const tok = data.split(",");
  const root = new Node(Number(tok[0]));
  const queue = [root];
  let i = 1;
  for (let h = 0; h < queue.length; h++) {
    while (tok[i] !== "#") {
      const c = new Node(Number(tok[i++]));
      queue[h].children.push(c);
      queue.push(c);
    }
    i++; // skip the #
  }
  return root;
}

function roundTrip(root: Nested | null): Nested | null {
  const toNode = (t: Nested): Node => { const n = new Node(t[0]); n.children = t[1].map(toNode); return n; };
  const toNested = (n: Node): Nested => [n.val, n.children.map(toNested)];
  const rebuilt = deserialize(serialize(root ? toNode(root) : null));
  return rebuilt ? toNested(rebuilt) : null;
}

